REPLACE = {'frontend/src/App.jsx': {'before': 'feb13ca6ad997fc11f137ef9de17e3c66d316fad246cf999de29cb223b937be3', 'after': 'import { Suspense, lazy, useCallback, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport Overview from \'./Overview\';\nimport FamilyChips from \'./FamilyChips\';\nimport ConfidenceBadge from \'./ConfidenceBadge\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport { attachTilt } from \'./tilt\';\nimport { attachInView } from \'./inView\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport RankingRevealCard from \'./cards/RankingRevealCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  // Routes live in the URL hash, so Back and Forward work: #/overview (the\n  // default) or #/case/<id>. The last case opened stays loaded behind the\n  // overview, so returning to it is instant.\n  const parseRoute = () => {\n    const m = window.location.hash.match(/^#\\/case\\/([\\w-]+)/);\n    return m ? { view: \'case\', id: m[1] } : { view: \'overview\', id: null };\n  };\n  const [route, setRoute] = useState(parseRoute);\n  useEffect(() => {\n    const on = () => setRoute(parseRoute());\n    window.addEventListener(\'hashchange\', on);\n    return () => window.removeEventListener(\'hashchange\', on);\n  }, []);\n  const [lastCase, setLastCase] = useState(route.id ?? \'case_0001\');\n  if (route.id && route.id !== lastCase) setLastCase(route.id);\n  const incidentId = route.id ?? lastCase;\n  const openCase = useCallback((id) => { window.location.hash = `#/case/${id}`; }, []);\n  const openOverview = useCallback(() => { window.location.hash = \'#/overview\'; }, []);\n  // family filter for the overview grid; the sidebar always lists every case\n  const [family, setFamily] = useState(\'all\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n  // each case\'s outcome and fit for the sidebar, from the same fields as the overview grid\n  const [summaries, setSummaries] = useState({});\n  useEffect(() => {\n    api.overview().then((rows) => setSummaries(Object.fromEntries(rows.map((r) => [r.incident_id, r.finding])))).catch(() => {});\n  }, []);\n  // hover tilt and light for every card, one listener for the app\n  useEffect(() => attachTilt(), []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid, route.view]);\n  // card motion plays as each card scrolls into view\n  useEffect(() => attachInView(document.querySelector(\'.finder-content\')), [vid, route.view]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && route.view === \'case\' && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          {route.view === \'case\' && vc && <ConfidenceBadge key={`conf-${vid}`} attribution={vc.attribution} />}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={openCase} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <button type="button" className={`nav-overview${route.view === \'overview\' ? \' is-active\' : \'\'}`} onClick={openOverview}>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 2h5v5H2zM9 2h5v5H9zM2 9h5v5H2zM9 9h5v5H9z" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" /></svg>\n            Overview\n          </button>\n          <CaseSwitcher incidents={incidents} active={route.view === \'case\' ? incidentId : null} onSelect={openCase} summaries={summaries} />\n        </aside>\n\n        {route.view === \'overview\' ? (\n          <Overview api={api} onOpen={openCase} family={family}\n                    chips={<FamilyChips incidents={incidents} value={family} onChange={setFamily} className="in-overview" />} />\n        ) : (\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                {/* ordered as the story is told: the answer, the proof, how it was reached, how robust\n                    it is, what it means, the raw evidence, what to check next, then methodology */}\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <RankingRevealCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} attribution={vc.attribution} />\n                <ForecastCard forecast={vc.forecast} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <NextObservationCard nextObs={vc.next_observation} closing />\n                {/* two supporting cards, side by side */}\n                <div className="card-row">\n                  <CoverageCard coverage={vc.coverage} />\n                  <ProvenanceCard meta={meta} report={shown.report} attribution={vc.attribution} />\n                </div>\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/cards/CaseFindingCard.jsx': {'before': 'ade2944abf1cc9c0a816e3952df50d50273848810d072a2d8697da9fd420a5a8', 'after': 'import { useEffect, useState } from \'react\';\nimport { Badge, Card } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\nimport { HowMeasured } from \'../ui/viz\';\nimport { useCountUp } from \'../ui/useCountUp\';\nimport { useInView } from \'../ui/useInView\';\nimport \'./caseFinding.css\';\n\n/**\n * Case Finding as one designed object, in the manner of a macOS widget: a hero\n * with the answer on the left and Fitness-style rings on the right, then the\n * proximity pick on a slim strip. A named case is blue: the outer ring is the\n * fit, with the gate marked, and the inner ring the forcing variants won. An\n * abstention is amber: the outer ring is the best fit and the inner ring the\n * gate it needed, so the shortfall is visible. Every value is a field of\n * attribution_result.json, naive_baseline_result.json or the case\'s vessels.\n */\nexport default function CaseFindingCard({ attribution, baseline, vessels }) {\n  if (!attribution || !baseline) return null;\n  const nearest = baseline.ranking[0];\n  const top = attribution.ranking[0];\n  const runnerUp = attribution.ranking[1];\n  const unknown = attribution.unknown_source;\n  const nCandidates = attribution.candidates_considered.length;\n  const disc = attribution.discrimination;\n  const gate = attribution.abstention_iou_gate;\n  const topVessel = vessels?.find((v) => v.vessel_key === top?.vessel_key);\n  const differs = !unknown && nearest && top && nearest.vessel_key !== top.vessel_key;\n  const km = nearest ? (nearest.distance_deg * 111).toFixed(1) : null;\n  const wins = top?.ensemble_win_count ?? 0, nVar = top?.n_ensemble ?? 6;\n  const fit = top?.mean_iou ?? 0;\n\n  const badge = unknown\n    ? <Badge tone="warning">System abstains</Badge>\n    : <Badge tone="accent">{differs ? \'Nearest vessel not supported\' : \'Candidate named\'}</Badge>;\n\n  const rings = unknown\n    ? [{ v: fit, label: \'Best fit\', value: fit.toFixed(2), tone: \'amber\' },\n       { v: gate, label: \'Gate to name\', value: String(gate), tone: \'sand\' }]\n    : [{ v: fit, label: \'Fit\', value: fit.toFixed(2), sub: `mean IoU · gate ${gate}`, tone: \'blue\', mark: gate },\n       { v: nVar ? wins / nVar : 0, label: \'Variants won\', value: `${wins}/${nVar}`, sub: \'forcing variants\', tone: \'teal\' }];\n\n  return (\n    <Card title="Case Finding" badge={badge} className={`finding cf3${unknown ? \' is-abstain\' : \'\'}`}>\n      <div className="cf3-hero">\n        <span className="cf3-glow" aria-hidden="true" />\n        <div className="cf3-main">\n          <span className="cf3-eyebrow">{unknown ? \'The system abstains\' : \'Forward replay names\'}</span>\n          <span className="cf3-key">{unknown ? \'No vessel named\' : top?.vessel_key}</span>\n          <span className="cf3-line">{unknown\n            ? `The best of ${nCandidates} replayed candidates fits at ${fit.toFixed(2)} — short of the ${gate} gate by ${(gate - fit).toFixed(2)}.`\n            : `The best physical fit of ${nCandidates} replayed candidates${runnerUp ? `, ahead of the runner-up at ${runnerUp.mean_iou.toFixed(2)}` : \'\'}.`}</span>\n          {!unknown && (\n            <span className="cf3-chips">\n              {topVessel?.first_entry_hours_before != null && <span className="cf3-chip">Inside the origin area {topVessel.first_entry_hours_before} h before</span>}\n              {disc?.discriminated === true && <span className="cf3-chip">Clear of the runner-up · gap {disc.loss_gap}</span>}\n              {disc?.discriminated === false && <span className="cf3-chip is-warn">Tied with the runner-up · gap {disc.loss_gap}</span>}\n            </span>\n          )}\n        </div>\n        <div className="cf3-side">\n          <Rings rings={rings} />\n          <div className="cf3-legend">\n            {rings.map((r) => (\n              <div key={r.label} className={`cf3-leg tone-${r.tone}`}>\n                <i />\n                <span className="cf3-leg-text"><em>{r.label}</em><b><Count text={r.value} /></b>{r.sub && <small>{r.sub}</small>}</span>\n              </div>\n            ))}\n          </div>\n        </div>\n      </div>\n\n      {nearest && (\n        <div className={`cf3-strip${differs ? \' is-struck\' : \'\'}`}>\n          <svg className="cf3-pin" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="2.4" /><circle cx="8" cy="8" r="5.6" /></svg>\n          <span className="cf3-strip-label">Proximity pick</span>\n          <span className="cf3-strip-key"><span>{nearest.vessel_key}</span></span>\n          <span className="cf3-strip-sub">nearest at image time · about {km} km away</span>\n          <span className={`cf3-verdict${differs ? \'\' : unknown ? \' is-neutral\' : \' is-agree\'}`}>\n            {differs ? \'not supported by forward replay\' : unknown ? \'not named either\' : \'also the best physical fit\'}</span>\n        </div>\n      )}\n\n      <p className="cf3-foot">{unknown\n        ? \'Declining is the output when no replayed release fits well enough; the source may be outside the data.\'\n        : \'A lead for an analyst, not proof of responsibility.\'}</p>\n      <HowMeasured>\n        <dl>\n          <dt>Proximity pick</dt><dd>{C.distance}</dd>\n          <dt>Fit (mean IoU)</dt><dd>{C.meanIou}</dd>\n          <dt>Fit gate</dt><dd>{C.fitGate}</dd>\n          {!unknown && <><dt>Variants won</dt><dd>Every release is replayed under six forcing variants; a win is a variant in which this vessel fits best of all candidates.</dd></>}\n          {!unknown && <><dt>Inside the origin area</dt><dd>{C.firstEntry}</dd></>}\n          {!unknown && <><dt>Gap to the runner-up</dt><dd>{C.lossGap}</dd></>}\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n\n/** Concentric rings, drawn in when they scroll into view; an optional tick marks the gate. */\nfunction Rings({ rings }) {\n  const [ref, seen] = useInView();\n  const [drawn, setDrawn] = useState(false);\n  useEffect(() => { if (!seen) return undefined; const id = requestAnimationFrame(() => setDrawn(true)); return () => cancelAnimationFrame(id); }, [seen]);\n  const R = [58, 42];\n  return (\n    <svg ref={ref} className="cf3-rings" viewBox="-70 -70 140 140" aria-hidden="true">\n      <defs>\n        <linearGradient id="cf3-blue" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#0a84ff" /><stop offset="1" stopColor="#64d2ff" /></linearGradient>\n        <linearGradient id="cf3-teal" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#30b0c7" /><stop offset="1" stopColor="#66e3d0" /></linearGradient>\n        <linearGradient id="cf3-amber" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#ff9f0a" /><stop offset="1" stopColor="#ffd60a" /></linearGradient>\n        <linearGradient id="cf3-sand" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#a2845e" /><stop offset="1" stopColor="#d4b483" /></linearGradient>\n      </defs>\n      {rings.map((r, i) => {\n        const rad = R[i], c = 2 * Math.PI * rad, f = Math.max(0.004, Math.min(1, r.v));\n        const a = (r.mark ?? 0) * 2 * Math.PI - Math.PI / 2;\n        return (\n          <g key={r.label} className={`cf3-ring tone-${r.tone}`}>\n            <circle r={rad} className="cf3-ring-track" />\n            <circle r={rad} className="cf3-ring-arc" stroke={`url(#cf3-${r.tone})`} transform="rotate(-90)"\n                    strokeDasharray={`${drawn ? c * f : 0} ${c}`} style={{ transitionDelay: `${i * 160}ms` }} />\n            {r.mark != null && <line x1={(rad - 9) * Math.cos(a)} y1={(rad - 9) * Math.sin(a)} x2={(rad + 9) * Math.cos(a)} y2={(rad + 9) * Math.sin(a)} className="cf3-mark" />}\n          </g>\n        );\n      })}\n    </svg>\n  );\n}\n\n/** A figure that counts up when seen; fractions like 5/6 count their first part. */\nfunction Count({ text }) {\n  const m = String(text).match(/^(\\d+(?:\\.\\d+)?)(.*)$/);\n  const [ref, seen] = useInView();\n  const decimals = m && m[1].includes(\'.\') ? m[1].split(\'.\')[1].length : 0;\n  const n = useCountUp(m ? Number(m[1]) : null, { decimals, duration: 900, run: seen });\n  return <span ref={ref}>{m ? <>{n}{m[2]}</> : text}</span>;\n}\n'}, 'frontend/src/cards/caseFinding.css': {'before': '8d500ab04d27d2412eb4e5cc749d73db1b6e9d2d6489ea7dc1416ed67ec6817c', 'after': '/* Case Finding: one hero surface - the answer on the left, rings on the right - then the proximity strip. */\n.cf3-hero { position: relative; overflow: hidden; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--space-6);\n            padding: 26px 28px; border-radius: 22px; isolation: isolate;\n            background: linear-gradient(145deg, rgba(10, 132, 255, 0.16), rgba(10, 132, 255, 0.04) 55%, rgba(100, 210, 255, 0.08));\n            box-shadow: inset 0 0 0 0.5px rgba(100, 180, 255, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.08); }\n.cf3.is-abstain .cf3-hero { background: linear-gradient(145deg, rgba(255, 159, 10, 0.16), rgba(255, 159, 10, 0.04) 55%, rgba(255, 214, 10, 0.07));\n                            box-shadow: inset 0 0 0 0.5px rgba(255, 190, 90, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.07); }\n/* a soft glow that drifts slowly behind the content - transform only, so it costs nothing */\n.cf3-glow { position: absolute; z-index: -1; width: 520px; height: 520px; right: -160px; top: -220px; border-radius: 50%; pointer-events: none;\n            background: radial-gradient(circle, rgba(10, 132, 255, 0.34), rgba(100, 210, 255, 0.10) 45%, transparent 70%);\n            filter: blur(10px); animation: cf3-drift 14s ease-in-out infinite alternate; }\n.cf3.is-abstain .cf3-glow { background: radial-gradient(circle, rgba(255, 159, 10, 0.32), rgba(255, 214, 10, 0.08) 45%, transparent 70%); }\n@keyframes cf3-drift { from { transform: translate(0, 0) scale(1); } to { transform: translate(-90px, 60px) scale(1.12); } }\n\n.cf3-main { min-width: 0; display: flex; flex-direction: column; gap: 8px; }\n.cf3-eyebrow { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.09em; color: var(--label-2); }\n.cf3.is-abstain .cf3-eyebrow { color: #ffb340; }\n.cf3-key { font-family: var(--font-mono); font-size: clamp(30px, 3.4vw, 46px); font-weight: 600; letter-spacing: -0.02em; line-height: 1.02;\n           overflow-wrap: anywhere; background: linear-gradient(95deg, #0a84ff 10%, #64d2ff 90%); -webkit-background-clip: text; background-clip: text; color: transparent;\n           animation: cf3-rise 700ms cubic-bezier(0.22, 1, 0.36, 1) backwards; }\n.cf3.is-abstain .cf3-key { font-family: var(--font-display); letter-spacing: -0.03em; background: linear-gradient(95deg, #ff9f0a 10%, #ffd60a 90%);\n                           -webkit-background-clip: text; background-clip: text; }\n@keyframes cf3-rise { from { opacity: 0; translate: 0 8px; } }\n.cf3-line { max-width: 44ch; font-size: var(--font-size-sm); line-height: 1.5; color: var(--label-1); opacity: 0.8; }\n.cf3-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }\n.cf3-chip { padding: 4px 10px; border-radius: 999px; font-size: var(--font-size-xs); color: var(--label-1);\n            background: color-mix(in srgb, var(--card-bg) 55%, transparent); box-shadow: inset 0 0 0 0.5px var(--separator-strong);\n            -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }\n.cf3-chip.is-warn { color: var(--status-orange); }\n\n.cf3-side { display: flex; align-items: center; gap: 18px; }\n.cf3-rings { width: 150px; height: 150px; overflow: visible; }\n.cf3-ring-track { fill: none; stroke-width: 12; stroke: var(--fill-pressed); }\n.cf3-ring-arc { fill: none; stroke-width: 12; stroke-linecap: round; transition: stroke-dasharray 1300ms cubic-bezier(0.22, 1, 0.36, 1); }\n.cf3-ring.tone-blue .cf3-ring-arc { filter: drop-shadow(0 0 6px rgba(10, 132, 255, 0.55)); }\n.cf3-ring.tone-teal .cf3-ring-arc { filter: drop-shadow(0 0 6px rgba(48, 176, 199, 0.5)); }\n.cf3-ring.tone-amber .cf3-ring-arc { filter: drop-shadow(0 0 6px rgba(255, 159, 10, 0.55)); }\n.cf3-mark { stroke: #fff; stroke-width: 2.5; stroke-linecap: round; opacity: 0.9; }\n.cf3-legend { display: flex; flex-direction: column; gap: 12px; min-width: 128px; }\n.cf3-leg { display: flex; align-items: flex-start; gap: 9px; }\n.cf3-leg i { flex: none; width: 10px; height: 10px; margin-top: 4px; border-radius: 50%; }\n.cf3-leg.tone-blue i { background: linear-gradient(135deg, #0a84ff, #64d2ff); } .cf3-leg.tone-teal i { background: linear-gradient(135deg, #30b0c7, #66e3d0); }\n.cf3-leg.tone-amber i { background: linear-gradient(135deg, #ff9f0a, #ffd60a); } .cf3-leg.tone-sand i { background: linear-gradient(135deg, #a2845e, #d4b483); }\n.cf3-leg-text { display: flex; flex-direction: column; }\n.cf3-leg-text em { font-style: normal; font-size: var(--font-size-xxs); text-transform: uppercase; letter-spacing: 0.07em; color: var(--label-2); }\n.cf3-leg-text b { font-family: var(--font-display); font-size: 24px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.15; color: var(--label-1); font-variant-numeric: tabular-nums; }\n.cf3-leg-text small { font-size: var(--font-size-xxs); color: var(--label-3); }\n\n/* the proximity pick, on a slim strip */\n.cf3-strip { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; margin-top: 14px; padding: 12px 16px; border-radius: 14px; background: var(--fill-pressed); }\n.cf3-pin { width: 16px; height: 16px; fill: none; stroke: var(--label-2); stroke-width: 1.4; }\n.cf3-strip-label { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.07em; color: var(--label-3); }\n.cf3-strip-key { position: relative; font-family: var(--font-mono); font-size: var(--font-size-md); color: var(--label-1); }\n.cf3-strip-key > span { position: relative; }\n.cf3-strip.is-struck .cf3-strip-key { color: var(--label-2); }\n.cf3-strip.is-struck .cf3-strip-key > span::after { content: ""; position: absolute; left: -2px; right: -2px; top: 54%; height: 1.5px; background: var(--status-orange);\n                                                    transform-origin: left; animation: cf-strike 520ms 700ms cubic-bezier(0.22, 1, 0.36, 1) backwards; }\n@keyframes cf-strike { from { transform: scaleX(0); } }\n.cf3-strip-sub { font-size: var(--font-size-xs); color: var(--label-2); }\n.cf3-verdict { margin-left: auto; padding: 3px 10px; border-radius: 999px; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold);\n               color: var(--status-orange); background: rgba(255, 159, 10, 0.12); }\n.cf3-verdict.is-agree { color: var(--status-green); background: rgba(48, 209, 88, 0.12); }\n.cf3-verdict.is-neutral { color: var(--label-2); background: rgba(128, 128, 128, 0.12); }\n.cf3-foot { margin: 14px 0 0; font-size: var(--font-size-sm); color: var(--label-2); }\n@media (max-width: 980px) { .cf3-hero { grid-template-columns: 1fr; } }\n@media (prefers-reduced-motion: reduce) {\n  .cf3-glow, .cf3-key, .cf3-strip.is-struck .cf3-strip-key > span::after { animation: none; }\n  .cf3-ring-arc { transition: none; }\n}\n'}}
CL_OLD = 'satellite over the recommended window, with the two vessels it would separate as chips.\n'
CL_NEW = "satellite over the recommended window, with the two vessels it would separate as chips.\n\n**Case Finding as one designed object, and the cards in story order.** Case Finding is a single\nhero in the manner of a macOS widget: the answer on the left, Fitness-style rings on the right -\nthe fit with the gate marked and the forcing variants won, or for an abstention the best fit\nagainst the gate it needed - over a slowly drifting glow, blue or amber, with the proximity pick on\na slim strip below. Named and abstaining cases share the layout. The case's cards now run in the\norder the story is told: the finding, the naive-versus-replay reveal, the replay map, rank\nfragility, forward exposure, the observed scene, the next observation, then methodology.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
